data = "C,B,A,B,B,B,C,B,B,A,C,B,C,B,B"
votes = data.split(',')
vote_counts = {}

for vote in votes:
    if vote in vote_counts:
        vote_counts[vote] += 1
    else:
        vote_counts[vote] = 1

sorted_vote_counts = dict(sorted(vote_counts.items(), key=lambda item: item[1], reverse=True))

for candidate, count in sorted_vote_counts.items():
    print(f"{candidate}: {count}")
